// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 actorSeed, uint256 roll, uint256 warpOffset) public {
        uint256 blockNumber = bound(roll, 1, 1_000_000);
        vm.roll(blockNumber);
        vm.warp(blockNumber + bound(warpOffset, 1, 1000));
        address actor = address(uint160(uint256(keccak256(abi.encode(actorSeed)))));
        vm.assume(actor != address(0));
        vm.deal(actor, 100 ether);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "call failed");

        if (blockNumber % 15 == 0) {
            assertEq(address(c).balance, 0, "Balance should be 0 after transfer");
        }
    }
}
